19	const PROCESSING_FEE = 5;
20	const FIRST_INSURANCE_SURCHARGE = 0.1;
21	
22	const SWORD_BASE_PREMIUM = 100;
23	const AMULET_BASE_PREMIUM = 60;
24	
25	const sum = (amounts: number[]): number =>
26	  amounts.reduce((total, amount) => total + amount, 0);
27	
28	const basePremiumOf = (item: Item): number =>
29	  item.type === "amulet" ? AMULET_BASE_PREMIUM : SWORD_BASE_PREMIUM;
30	
31	const quotePremium = (items: Item[]): number => {
32	  const basePremium = sum(items.map(basePremiumOf));
33	
34	  return (
35	    basePremium + basePremium * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE
36	  );
37	};
38	
39	export const runScenario = (scenario: Scenario): ScenarioResult => ({
40	  results: scenario.steps.map((step) => ({
41	    premium: quotePremium(step.items),
42	  })),
43	});
